using System.Text.Json;
using System.Xml.Linq;
using Studio.Core;
using Studio.Raple;
using TKR.Shared.resources;
using TKR.WorldServer.core.objects;

var adapter = new RapleAdapter(Path.GetFullPath(args.FirstOrDefault() ?? "../raple-realms-7-server"));
var count = 0;
void Check(bool result, string label) { if (!result) throw new Exception(label); Console.WriteLine("PASS " + label); count++; }
var square = new HitGeometry(.5); var circle = new HitGeometry(.5, true);
Check(square.Contains(.5, 0) && square.Contains(.5, .5) && !square.Contains(.500001, 0), "Client square boundaries are inclusive, with no projectile radius");
Check(!circle.Contains(.4, .4) && circle.Contains(.5, 0), "Client circular targets exclude square corners");
Check(ClientCollision.Geometry(0x6930) == new HitGeometry(2.25, true) && ClientCollision.Geometry(0x6931) == new HitGeometry(1.2, true), "Oryx IV hit radii read from actual game XML");
HitTarget Target(int id, double x, double y, bool eligible = true, ushort type = 1) => new(id, type, x, y, square, eligible);
Check(ClientCollision.Select(0, 0, [Target(1, .4, .4), Target(2, -.4, -.4)])?.Id == 1, "Equal-distance client target order is stable");
Check(ClientCollision.Select(0, 0, [Target(1, .1, 0, false), Target(2, .4, 0)])?.Id == 2, "Unhittable target does not swallow a projectile");
Check(ClientCollision.Select(0, 0, [Target(1, .1, 0), Target(2, .4, 0, type: 0x6931)])?.Id == 2, "Heart of the Hour preserves client hit priority");
Check(ClientCollision.Select(0, 0, [Target(1, .1, 0), Target(2, .4, 0)], new HashSet<int> { 1 })?.Id == 2, "Piercing projectile skips targets already hit");
var parametric = new ProjectileDesc(XElement.Parse("<Projectile><ObjectId>Red Bullet</ObjectId><Speed>100</Speed><Damage>50</Damage><LifetimeMS>1000</LifetimeMS><Parametric/><Magnitude>2</Magnitude></Projectile>"));
var path = new Player.ValidatedProjectile(0, false, 0, 10, 10, 0, 0, 50, false, true);
Check(Math.Abs(ClientTrajectory.Sample(path, 250, 0, parametric).X - 8) < .00001 && Math.Abs(ClientTrajectory.Sample(path, 250, 1, parametric).X - 12) < .00001, "Parametric X parity matches Projectile.as rather than divergent server validation");
var weapons = GameWeapon.Catalog();
Check(weapons.Count > 100 && weapons.Any(w => w.Id == "Bow of Fey Magic" && w.Supported), "Weapon catalog uses real equipment slot definitions");
Console.WriteLine($"Catalog: {weapons.Count(w => w.Supported)} supported / {weapons.Count} total weapons");
var original = File.ReadAllText(Path.Combine(adapter.ServerRoot, "TKR.WorldServer/logic/db/BehaviorDb.PirateCave.cs"));
var doc = new BehaviorDocument(original, adapter);
var root = doc.Entities.Single(e => e.EntityId == "Cave Pirate Brawler").Root;
doc.ReplaceSource(doc.Source.Remove(root.Start, root.Length).Insert(root.Start, "new State(\"idle\")"));
EncounterSession Run(string weapon, int ticks, bool attack = true, double aimX = 64.5, int dex = 50, int atk = 50)
{
    var run = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new(WeaponId: weapon, Dexterity: dex, Attack: atk));
    for (var i = 0; i < ticks; i++) run.Step(new(Attack: attack, AimX: aimX, AimY: 64.5));
    return run;
}
var bow = Run("Bow of Fey Magic", 1);
Check(bow.PlayerShots.Count == 3 && bow.PlayerShots.Select(p => p.Ms).Distinct().Single() == 0, "XML bow emits three pellets as one volley");
Check(Math.Abs((bow.PlayerShots[1].Angle - bow.PlayerShots[0].Angle) * 180 / Math.PI - 8) < .0001, "XML ArcGap defines bow spread");
Check(bow.PlayerShots.All(p => p.Damage >= 72 && p.Damage < 98), "Original seeded damage generator applies normal attack multiplier");
Check(Math.Abs(bow.PlayerShots[0].X - 70.2) < .0001 && Math.Abs(bow.PlayerShots[0].Y - 64.5) < .0001, "Pellets share client muzzle offset along aim direction");
var miss = Run("Archon Sword", 30);
Check(miss.BossHp == miss.BossMaxHp && !miss.Events.Any(e => e.Kind == "weapon-hit"), "Sword beyond XML range cannot damage the boss");
var away = Run("Staff of Diabolic Secrets", 30, aimX: 100);
Check(away.BossHp == away.BossMaxHp, "Projectiles aimed away cannot act as an instant ray");
var staff = Run("Staff of Diabolic Secrets", 30);
Check(staff.Events.Any(e => e.Kind == "weapon-hit") && staff.BossHp < staff.BossMaxHp, "Real staff projectiles damage the target through native Player.EnemyHit");
var repeat = Run("Staff of Diabolic Secrets", 30);
Check(JsonSerializer.Serialize(staff.PlayerShots) == JsonSerializer.Serialize(repeat.PlayerShots) && JsonSerializer.Serialize(staff.Events) == JsonSerializer.Serialize(repeat.Events), "Recorded weapon firing and damage replay deterministically");
Check(Run("Staff of Diabolic Secrets", 10, dex: 75).PlayerShots.Count > Run("Staff of Diabolic Secrets", 10, dex: 0).PlayerShots.Count, "Native dexterity changes firing cadence");
var bonus = Run("Staff of Esben", 1, aimX: 100);
Check(bonus.PlayerStats[2] == 51 && bonus.PlayerStats[4] == 53, "XML IncrementStat equip bonuses feed original stat managers");
var slowStaff = Run("Staff of Esben", 10, aimX: 100, dex: 75);
Check(slowStaff.PlayerShots.Count < Run("Staff of Diabolic Secrets", 10, aimX: 100, dex: 75).PlayerShots.Count, "Weapon RateOfFire multiplies native dexterity cadence");
var boosted = Run("Defense Boost Test Staff", 7, aimX: 100, dex: 75);
Check(boosted.PlayerStats[3] == 35, "Sixth-volley defense boost applies after the complete volley");
for (var i = 0; i < 30; i++) boosted.Step(new());
Check(boosted.PlayerStats[3] == 25, "Temporary shot boost expires without further attacks");
var speedy = Run("Speedy Status Test Staff", 7, aimX: 100, dex: 75);
var normal = Run("Staff of Diabolic Secrets", 7, aimX: 100, dex: 75);
var sy = speedy.PlayerY; var ny = normal.PlayerY; speedy.Step(new(Y: 1)); normal.Step(new(Y: 1));
Check(Math.Abs((speedy.PlayerY - sy) / (normal.PlayerY - ny) - 1.35) < .002, "OnShoot status feeds original condition manager and client movement");
var sixth = Run("Sixth Shot Test Staff", 7, aimX: 100, dex: 75).PlayerShots.GroupBy(p => p.Ms).ToArray();
Check(sixth[5].All(p => p.Index == 1 && p.Damage >= 165) && sixth[4].All(p => p.Index == 0 && p.Damage < 143), "Sixth-shot proc switches to the XML damage range");
var volley = Run("Staff of Shifting Arms", 65, aimX: 100, dex: 75);
var volleys = volley.PlayerShots.GroupBy(p => p.Ms).Take(20).ToArray();
Check(volleys.Length == 20 && new[] { 4, 9, 14, 19 }.Select(i => volleys[i].First().Index).SequenceEqual(new[] { 1, 2, 3, 4 }), "Original OnShoot tracker cycles bow, sword, katana and dagger every fifth attack");
Check(volleys[4].Count() == 3 && volleys[9].Count() == 1 && Math.Abs((volleys[4].ElementAt(1).Angle - volleys[4].First().Angle) * 180 / Math.PI - 8) < .0001, "Cycling proc overrides XML projectile count and spread");
var kill = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new()); kill.SetBossHpFraction(.001);
for (var i = 0; i < 15; i++) kill.Step(new(Attack: true, AimX: 64.5, AimY: 64.5));
Check(kill.Events.Any(e => e.Kind == "death" && e.Message.Contains("native death callbacks")) && kill.Entities.Count == 0, "Weapon death executes native callbacks and removes the enemy");
var outDir = Path.GetFullPath(".artifacts/weapons"); Directory.CreateDirectory(outDir);
var saved = Path.Combine(outDir, "preset.rbs");
BehaviorDocument.Save(saved, new StudioProject { Source = doc.Source, Player = new(WeaponId: "Bow of Fey Magic", Attack: 60, Dexterity: 75) });
Check(BehaviorDocument.Load(saved).Player is { WeaponId: "Bow of Fey Magic", Attack: 60, Dexterity: 75 }, "Weapon preset survives save and reopen");
Check(JsonSerializer.Deserialize<PlayerPreset>("{\"Hp\":900,\"Speed\":50,\"Defense\":0}") is { WeaponId: "Staff of Diabolic Secrets", Attack: 50, Dexterity: 50 }, "Older projects receive backward-compatible weapon defaults");
Check(weapons.Single(w => w.Id == "Cursor Grenade Test Staff").Limitation?.Contains("grenade") == true, "Unimplemented grenade proc is explicitly unavailable");
staff.ExportTrace(Path.Combine(outDir, "staff-trace.json")); volley.ExportTrace(Path.Combine(outDir, "cycling-trace.json"));
var smooth = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
var playerStart = smooth.PlayerY; smooth.Advance(new(Y: 1), 15);
Check(smooth.Ms == 15 && smooth.PlayerY > playerStart && smooth.PlayerY - playerStart < .15, "Player advances within one display frame instead of waiting 100 ms");
var fixedRun = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
for (var i = 0; i < 10; i++) fixedRun.Step(new(Y: 1, Attack: true, AimX: 100, AimY: 64.5));
var splitRun = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
for (var i = 0; i < 10; i++) foreach (var duration in new[] { 15, 20, 15, 15, 20, 15 }) splitRun.Advance(new(Y: 1, Attack: true, AimX: 100, AimY: 64.5), duration);
Check(splitRun.Ms == fixedRun.Ms && splitRun.PlayerX == fixedRun.PlayerX && splitRun.PlayerY == fixedRun.PlayerY && JsonSerializer.Serialize(splitRun.PlayerShots) == JsonSerializer.Serialize(fixedRun.PlayerShots), "Display-frame partitioning preserves movement and weapon timing exactly");
var movingDoc = new BehaviorDocument(original, adapter);
var fixedEnemy = new EncounterSession(adapter, movingDoc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
for (var i = 0; i < 40; i++) fixedEnemy.Step(new(Y: 1));
var smoothEnemy = new EncounterSession(adapter, movingDoc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
for (var i = 0; i < 40; i++) foreach (var duration in new[] { 15, 20, 15, 15, 20, 15 }) smoothEnemy.Advance(new(Y: 1), duration);
Check(JsonSerializer.Serialize(smoothEnemy.Shots) == JsonSerializer.Serialize(fixedEnemy.Shots) && JsonSerializer.Serialize(smoothEnemy.Events) == JsonSerializer.Serialize(fixedEnemy.Events) && smoothEnemy.PlayerHp == fixedEnemy.PlayerHp, "Smooth frames preserve independent 100 ms enemy ticks, collision and effects");
var recorded = new EncounterSession(adapter, doc, "Cave Pirate Brawler", 7, new(Invulnerable: true));
foreach (var entry in splitRun.Inputs) recorded.Advance(entry.Input, entry.DurationMs);
Check(recorded.PlayerY == splitRun.PlayerY && JsonSerializer.Serialize(recorded.PlayerShots) == JsonSerializer.Serialize(splitRun.PlayerShots), "Replay records retain display-frame input durations");
File.WriteAllText(Path.Combine(outDir, "catalog.json"), JsonSerializer.Serialize(weapons, BehaviorDocument.JsonOptions));
var ghostProjectiles = EnemyProjectiles.ForEntity("Ghost Ship");
Check(ghostProjectiles.Select(p => p.Index).SequenceEqual([0, 1]) && ghostProjectiles[1] is { TextureId: "Giant Cannonball", MinDamage: 250, MaxDamage: 250, LifetimeMs: 4000, Speed: 65 }, "Enemy projectile catalog retains real XML IDs, textures, damage, lifetime and speed without renumbering");
Check(EnemyProjectiles.ForEntity("Cave Pirate Brawler").Single() is { Index: 0, TextureId: "Blade", MinDamage: 5 } && EnemyProjectiles.ForEntity("No such enemy").Count == 0, "Projectile choices belong to the requested XML owner and unknown entities never borrow another catalog");
var ghostXml = XElement.Load(Path.Combine(adapter.ServerRoot, "TKR.Shared/resources/xml/characters/TK_Characters_chars16x16rEncounters.xml")).Elements("Object").Single(e => (string?)e.Attribute("id") == "Ghost Ship");
Check(ghostXml.Elements("Projectile").Select(e => (int)e.Attribute("id")!).SequenceEqual(ghostProjectiles.Select(p => p.Index)) && ghostXml.Elements("Projectile").All(e => ghostProjectiles.Single(p => p.Index == (int)e.Attribute("id")!).TextureId == (string)e.Element("ObjectId")!), "Picker IDs and texture references agree with the supplied XML file independently of its native descriptor lookup");
var ghostDoc = new BehaviorDocument("class Fixture { void Build() { db.Init(\"Ghost Ship\", new State(new Shoot(8, projectileIndex: 1, fixedAngle: 0, coolDown: 100))); } }", adapter);
using (var ghostSession = new EncounterSession(adapter, ghostDoc, "Ghost Ship", 7, new()))
{
    ghostSession.Step(new());
    Check(ghostSession.Shots.Single() is { Index: 1, Damage: 250 } && ghostSession.Projectiles.Single().TextureId == "Giant Cannonball", "Selected XML index executes the real Ghost Ship projectile packet, damage and texture through native Shoot");
}
Console.WriteLine($"{count} collision/weapon checks passed.");
